#include <stdio.h>

union Value {
    int number;
    char letter;
};

int main() {
    union Value v;
    v.number = 65;
    printf("As number: %d\n", v.number);
    printf("As letter: %c\n", v.letter);
    printf("Big enough for an int: %d\n", (int)sizeof(union Value) >= (int)sizeof(int));
    return 0;
}
